import Foundation
import Network

/// Credentials from the bundled Secrets.plist (generated by deploy.sh, git-ignored).
enum Secrets {
    private static let values = Bundle.main.url(forResource: "Secrets", withExtension: "plist")
        .flatMap { NSDictionary(contentsOf: $0) }

    /// The value, or nil if it is missing or empty.
    static func string(_ key: String) -> String? {
        guard let value = values?[key] as? String, !value.isEmpty else { return nil }
        return value
    }
}

enum ServiceError: LocalizedError {
    case missing(String)
    case http(Int, String?)
    case api(String)
    case badResponse

    var errorDescription: String? {
        switch self {
        case .missing(let what): return "no \(what) in Secrets.plist"
        case .http(let code, let message): return message.map { "HTTP \(code): \($0)" } ?? "HTTP \(code)"
        case .api(let message): return message
        case .badResponse: return "unexpected response"
        }
    }
}

private let session: URLSession = {
    let config = URLSessionConfiguration.ephemeral
    config.timeoutIntervalForRequest = 20
    return URLSession(configuration: config)
}()

/// Sends a request and completes on the main queue with the JSON object. A status
/// other than 200 fails, with the message from the body's `errorKey` if there is one.
func fetchJSON(_ request: URLRequest, errorKey: String? = nil,
               completion: @escaping (Result<[String: Any], Error>) -> Void) {
    var request = request
    #if DEBUG
    if Connectivity.shared.debugFailing { request.url = URL(string: "http://127.0.0.1:9/") }
    #endif
    session.dataTask(with: request) { data, response, error in
        let json = data.flatMap { (try? JSONSerialization.jsonObject(with: $0)) as? [String: Any] }
        DispatchQueue.main.async {
            Connectivity.shared.requestFinished(gotResponse: response != nil)
            if let error = error {
                completion(.failure(error))
            } else if let http = response as? HTTPURLResponse, http.statusCode != 200 {
                let message = errorKey.flatMap { json?[$0] as? String }
                completion(.failure(ServiceError.http(http.statusCode, message)))
            } else if let json = json {
                completion(.success(json))
            } else {
                completion(.failure(ServiceError.badResponse))
            }
        }
    }.resume()
}

/// Whether the app can reach anything, judged from the pages' own fetches: any
/// HTTP response (even an error status) proves the network works, so one service
/// being down doesn't count. iOS also says when there is no connection at all
/// (Airplane mode, no Wi-Fi), which is reported much sooner. See `outage`.
final class Connectivity {
    static let shared = Connectivity()
    static let didChange = Notification.Name("Connectivity.didChange")
    /// No answer from any server this long is an outage (red banner, "No network").
    static let alertAfter: TimeInterval = 20 * 60
    /// No connection at all this long is an outage too.
    static let noConnectionAlertAfter: TimeInterval = 2 * 60

    private let monitor = NWPathMonitor()
    /// When iOS last went from a connection to none.
    private var noConnectionSince: Date?

    private init() {
        monitor.pathUpdateHandler = { [weak self] path in
            DispatchQueue.main.async { self?.pathChanged(connected: path.status == .satisfied) }
        }
        monitor.start(queue: DispatchQueue(label: "Connectivity"))
    }

    private func pathChanged(connected: Bool) {
        guard connected == (noConnectionSince != nil) else { return }
        noConnectionSince = connected ? nil : Date()
        NotificationCenter.default.post(name: Connectivity.didChange, object: nil)
    }

    /// How long the network has been out, once that counts as an outage: no
    /// connection for `noConnectionAlertAfter`, or no answer for `alertAfter`.
    /// Measured from the earlier of the two. Nil while there is no outage.
    var outage: TimeInterval? {
        let now = Date()
        let starts = [offlineSince.map { ($0, Connectivity.alertAfter) },
                      noConnectionSince.map { ($0, Connectivity.noConnectionAlertAfter) }].compactMap { $0 }
        guard starts.contains(where: { now.timeIntervalSince($0.0) >= $0.1 }) else { return nil }
        return starts.map { now.timeIntervalSince($0.0) }.max()
    }

    /// When requests started failing with no response from anywhere in between.
    private var offlineSince: Date?
    /// When any request last got an answer.
    private(set) var lastResponse: Date?

    #if DEBUG
    // simctl launch ... with SIMCTL_CHILD_IPADDASH_OFFLINE_AGE=<minutes> fails every
    // request and back-dates the outage; IPADDASH_OFFLINE_SECS=<n> ends it after n seconds.
    private let debugAge = ProcessInfo.processInfo.environment["IPADDASH_OFFLINE_AGE"].flatMap(Double.init)
    private let debugEnd = ProcessInfo.processInfo.environment["IPADDASH_OFFLINE_SECS"]
        .flatMap(Double.init).map { Date().addingTimeInterval($0) }
    fileprivate var debugFailing: Bool {
        return debugAge != nil && (debugEnd.map { Date() < $0 } ?? true)
    }
    #endif

    /// How long the network has been gone, or nil while it works.
    var offlineDuration: TimeInterval? {
        return offlineSince.map { Date().timeIntervalSince($0) }
    }

    /// Main queue only.
    fileprivate func requestFinished(gotResponse: Bool) {
        if gotResponse { lastResponse = Date() }
        guard gotResponse == (offlineSince != nil) else { return }
        offlineSince = gotResponse ? nil : Date()
        #if DEBUG
        if !gotResponse, let age = debugAge { offlineSince = Date().addingTimeInterval(-age * 60) }
        #endif
        NotificationCenter.default.post(name: Connectivity.didChange, object: nil)
    }
}
